#pragma once
#include "common.hpp"
namespace mg {
inline double hist_point(const Data&d,int a,int target,int key,bool correct=true){int day=a/DAY,t=target%DAY;const auto&x=d.series(key);double pred;if(key!=1){int h=target/DAY;while(h>=day)h-=7;while(h<0)h+=7;if(h>=day)h=day-1;pred=x[h*DAY+t];}else{pred=0;int h0=std::max(0,day-7);for(int h=h0;h<day;h++)pred+=x[h*DAY+t];pred/=day-h0;}if(correct&&a%DAY){int begin=std::max(day*DAY,a-36);double error=0;for(int u=begin;u<a;u++)error+=x[u]-hist_point(d,day*DAY,u,key,false);error/=a-begin;pred+=.8*error*std::exp(-(target-a)/36.);}return std::max(0.,pred);}
inline double official(const Data&d,int release,int target){int lag=target-release;if(lag<0||lag>=144||release<0)return std::numeric_limits<double>::quiet_NaN();int idx=(release/DAY*4+release%DAY/36)*24;double z=(lag+1)/6.;int i=(int)std::floor(z);double a=i==0?(release?d.pv[release-1]:0.):d.forecast[idx+i-1];double b=d.forecast[idx+std::min(i,23)];return std::max(0.,a+(z-i)*(b-a));}
inline Forecast prediction(const Data&d,int asof,int end,Kind k,int mode){Forecast f;int rel=asof/36*36;double olderr=0;if(mode&&k.official&&rel>=36){int old=rel-36,count=0;for(int t=rel-36;t<rel;t++){double p=official(d,old,t);if(std::isfinite(p)){olderr+=d.pv[t]-p;count++;}}if(count)olderr/=count;}for(int t=asof;t<end;t++){double l=hist_point(d,asof,t,0),v=hist_point(d,asof,t,1),p=k.variable?hist_point(d,asof,t,2):d.dayprice[t%144];if(k.official&&t-rel<144){double o=official(d,rel,t);if(mode){o=std::max(0.,o+.25*olderr*std::exp(-(t-rel)/36.));double alpha=mode==2?.5:.75;v=alpha*o+(1-alpha)*v;}else v=o;}f.load.push_back(l);f.pv.push_back(v);f.p.push_back(std::max(.001,p));f.net.push_back((l-v)/6.);}if(mode&&asof%DAY==0){double en=0,ep=0;for(int u=asof-36;u<asof;u++){en+=d.net(u)-(hist_point(d,asof-DAY,u,0)-hist_point(d,asof-DAY,u,1))/6;ep+=d.price[u]-hist_point(d,asof-DAY,u,2);}en/=36;ep/=36;for(int j=0;j<end-asof;j++){f.net[j]+=.35*en*std::exp(-j/36.);if(k.variable)f.p[j]=std::max(.001,f.p[j]+.35*ep*std::exp(-j/36.));}}return f;}
inline std::array<double,2>context(const Data&d,int a,bool variable){double n=0,p=0;for(int u=a-36;u<a;u++){n+=(d.net(u)-(hist_point(d,a-DAY,u,0)-hist_point(d,a-DAY,u,1))/6)/36;if(variable)p+=(d.price[u]-hist_point(d,a-DAY,u,2))/36;}return{n/100,p/.1};}
inline Scenario scenarios(const Data&d,int asof,int end,Kind k,const Config&c){int T=end-asof,day=asof/144;Scenario a;a.T=T;a.asof=asof;a.end=end;std::vector<int>hist;for(int h=day-1;h>=8&&hist.size()<28;h--){int ha=h*144+asof%144;if(ha+T<=asof)hist.push_back(ha);}std::reverse(hist.begin(),hist.end());check(!hist.empty(),"no mature history");if(c.scenario==0&&hist.size()>(size_t)c.count){std::vector<int>x;for(int i=0;i<c.count;i++)x.push_back(hist[std::round(i*(hist.size()-1.)/(c.count-1))]);hist=x;}auto cur=prediction(d,asof,end,k,c.predict);a.S=hist.size();a.w.assign(a.S,1./a.S);a.n.resize(a.S*T);a.p.resize(a.S*T);a.history=hist;auto current=context(d,asof,k.variable);double sum=0;for(int i=0;i<a.S;i++){int ha=hist[i];check(ha+T<=asof,"immature block");a.last_mature=std::max(a.last_mature,ha+T);auto old=prediction(d,ha,ha+T,k,c.predict);for(int j=0;j<T;j++){a.n[i*T+j]=cur.net[j]+d.net(ha+j)-old.net[j];a.p[i*T+j]=k.variable?std::max(.001,cur.p[j]+d.price[ha+j]-old.p[j]):cur.p[j];}if(c.scenario==1){auto ctx=context(d,ha,k.variable);a.w[i]=std::exp(-.5*(sq(ctx[0]-current[0])+sq(ctx[1]-current[1]))/sq(c.bandwidth));}sum+=a.w[i];}for(auto&w:a.w){double z=sum>1e-200?w/sum:1./a.S;w=c.scenario==1?(1-c.mixture)*z+c.mixture/a.S:1./a.S;}a.ess=1/std::inner_product(a.w.begin(),a.w.end(),a.w.begin(),0.);if(a.S>c.count){int n=a.S;Vec dist(n*n);for(int i=0;i<n;i++)for(int j=0;j<i;j++){double v=0;for(int q=0;q<T;q++){v+=sq((a.N(i,q)-a.N(j,q))/100);if(k.variable)v+=sq((a.P(i,q)-a.P(j,q))/.1);if(c.metric){double ref=pos(cur.net[q]);for(double offset:{-150.,0.,150.}){double ci=5*a.P(i,q)*pos(a.N(i,q)-ref+offset),cj=5*a.P(j,q)*pos(a.N(j,q)-ref+offset);v+=.25/3*sq((ci-cj)/500.);}}}dist[i*n+j]=dist[j*n+i]=std::sqrt(v/T);}std::vector<int>ids;Vec best(n,1e100);for(int z=0;z<c.count;z++){int at=-1;double val=1e300;for(int j=0;j<n;j++)if(std::find(ids.begin(),ids.end(),j)==ids.end()){double v=0;for(int i=0;i<n;i++)v+=a.w[i]*std::min(best[i],dist[i*n+j]);if(v<val){at=j;val=v;}}ids.push_back(at);for(int i=0;i<n;i++)best[i]=std::min(best[i],dist[i*n+at]);}Scenario b=a;b.S=ids.size();b.n.clear();b.p.clear();b.w.assign(b.S,0);b.history.clear();for(int x:ids){b.n.insert(b.n.end(),a.n.begin()+x*T,a.n.begin()+(x+1)*T);b.p.insert(b.p.end(),a.p.begin()+x*T,a.p.begin()+(x+1)*T);b.history.push_back(hist[x]);}for(int i=0;i<n;i++){int j=0;for(int l=1;l<b.S;l++)if(dist[i*n+ids[l]]<dist[i*n+ids[j]])j=l;b.w[j]+=a.w[i];b.transport+=a.w[i]*best[i];}a=std::move(b);}a.states();return a;}
struct Scores{double mae=0,point=0,pvmae=0,se=0,crps=0,cov=0,width=0,pmae=0,pcrps=0,pcov=0,pwidth=0,energy=0,variogram=0;long n=0,vn=0;void add(const Data&d,int asof,const Scenario&s,const Forecast&f){int H=std::min(144,s.T);for(int j=0;j<H;j++){double actual=d.net(asof+j),ap=d.price[asof+j];bool fixed=true;for(int i=1;i<s.S;i++)if(s.P(i,j)!=s.P(0,j))fixed=false;if(fixed)ap=s.P(0,j);Vec ns(s.S),ps(s.S);double m=0,mp=0;for(int i=0;i<s.S;i++){ns[i]=s.N(i,j);ps[i]=s.P(i,j);m+=s.w[i]*ns[i];mp+=s.w[i]*ps[i];crps+=s.w[i]*std::abs(ns[i]-actual);pcrps+=s.w[i]*std::abs(ps[i]-ap);energy+=s.w[i]*std::hypot((ns[i]-actual)/100,(ps[i]-ap)/.1);for(int l=0;l<s.S;l++){crps-=.5*s.w[i]*s.w[l]*std::abs(ns[i]-s.N(l,j));pcrps-=.5*s.w[i]*s.w[l]*std::abs(ps[i]-s.P(l,j));energy-=.5*s.w[i]*s.w[l]*std::hypot((ns[i]-s.N(l,j))/100,(ps[i]-s.P(l,j))/.1);}}auto wq=[&](Vec x,double q){std::vector<int>ix(s.S);std::iota(ix.begin(),ix.end(),0);std::sort(ix.begin(),ix.end(),[&](int a,int b){return x[a]<x[b];});double w=0;for(int i:ix){w+=s.w[i];if(w>=q)return x[i];}return x[ix.back()];};double lo=wq(ns,.05),hi=wq(ns,.95),pl=wq(ps,.05),ph=wq(ps,.95);mae+=std::abs(m-actual);point+=std::abs(f.net[j]-actual);pvmae+=std::abs(f.pv[j]-d.pv[asof+j]);se+=sq(m-actual);cov+=actual>=lo&&actual<=hi;width+=hi-lo;pmae+=std::abs(mp-ap);pcov+=ap>=pl&&ap<=ph;pwidth+=ph-pl;n++;for(int lag:{6,36})if(j>=lag){double v1=0,v2=0,v3=0;for(int h=0;h<s.S;h++){v1+=s.w[h]*std::sqrt(std::abs((s.N(h,j)-s.N(h,j-lag))/100));v2+=s.w[h]*std::sqrt(std::abs((s.P(h,j)-s.P(h,j-lag))/.1));v3+=s.w[h]*std::sqrt(std::abs(s.N(h,j)/100-s.P(h,j)/.1));}variogram+=sq(std::sqrt(std::abs((actual-d.net(asof+j-lag))/100))-v1)+sq(std::sqrt(std::abs((ap-(fixed?s.P(0,j-lag):d.price[asof+j-lag]))/.1))-v2)+sq(std::sqrt(std::abs(actual/100-ap/.1))-v3);vn+=3;}}}void save(const fs::path&p)const{std::ofstream f(p);f<<"pairs,net_point_mae,net_distribution_mean_mae,net_rmse,net_crps,net90_coverage,net90_width,price_mae,price_crps,price90_coverage,price90_width,energy,variogram,pv_mae\n"<<std::setprecision(17)<<n<<','<<point/n<<','<<mae/n<<','<<std::sqrt(se/n)<<','<<crps/n<<','<<cov/n<<','<<width/n<<','<<pmae/n<<','<<pcrps/n<<','<<pcov/n<<','<<pwidth/n<<','<<energy/n<<','<<variogram/std::max(1L,vn)<<','<<pvmae/n<<'\n';}};
}
